(()=>{const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const slides=[...document.querySelectorAll('.slide')],dots=[...document.querySelectorAll('[data-slide]')],pause=document.querySelector('#pauseSlides');let current=0,timer=null,paused=reduced;function show(index){current=index;slides.forEach((s,i)=>s.classList.toggle('active',i===index));dots.forEach((d,i)=>{d.classList.toggle('active',i===index);d.setAttribute('aria-pressed',String(i===index))})}function restart(){clearInterval(timer);timer=null;if(!paused&&!document.hidden&&slides.length>1)timer=setInterval(()=>show((current+1)%slides.length),5500)}dots.forEach(d=>d.addEventListener('click',()=>{show(Number(d.dataset.slide));restart()}));if(pause){pause.setAttribute('aria-pressed',String(paused));pause.textContent=paused?'▶':'Ⅱ';pause.addEventListener('click',()=>{paused=!paused;pause.setAttribute('aria-pressed',String(paused));pause.textContent=paused?'▶':'Ⅱ';restart()})}document.addEventListener('visibilitychange',restart);restart();if(!reduced&&'IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e));document.documentElement.classList.add('motion-ready')}})();

(()=>{const video=document.querySelector('#homeVideo'),button=document.querySelector('#pauseHomeVideo'),full=document.querySelector('#kafrQaraVideo');if(!video||!button)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)');let userPaused=reduced.matches;video.muted=true;function sync(){button.textContent=video.paused?'▶':'Ⅱ';button.setAttribute('aria-pressed',String(video.paused));button.setAttribute('aria-label',I18N.t(video.paused?'تشغيل الفيديو':'إيقاف الفيديو'))}function play(){if(!document.hidden&&(!full||full.paused))video.play().catch(sync)}video.addEventListener('play',sync);video.addEventListener('pause',sync);button.addEventListener('click',()=>{userPaused=!video.paused;if(userPaused)video.pause();else play()});document.addEventListener('visibilitychange',()=>{if(document.hidden)video.pause();else if(!userPaused)play()});reduced.addEventListener('change',e=>{userPaused=e.matches;if(userPaused)video.pause();else play()});if(full){full.addEventListener('play',()=>video.pause());full.addEventListener('pause',()=>{if(!userPaused)play()});full.addEventListener('ended',()=>{if(!userPaused)play()})}window.addEventListener('languagechange',sync);if(userPaused){video.removeAttribute('autoplay');video.pause()}else play();sync()})();

(()=>{const button=document.querySelector('#pauseTicker'),ticker=document.querySelector('.moving-ticker');if(!button||!ticker)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)');let paused=reduced.matches;function sync(){ticker.dataset.paused=String(paused);button.disabled=reduced.matches;button.textContent=paused?'▶':'Ⅱ';button.setAttribute('aria-pressed',String(paused));button.setAttribute('aria-label',I18N.t(paused?'تشغيل حركة الشريط':'إيقاف حركة الشريط'))}button.addEventListener('click',()=>{paused=!paused;sync()});reduced.addEventListener('change',e=>{paused=e.matches;sync()});window.addEventListener('languagechange',sync);sync()})();
